package com.smartresponse.api;
import com.smartresponse.domain.EmergencyStatus; import com.smartresponse.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/admin/metrics") public class AdminMetricsController {private final EmergencyRepository emergencies;private final ShelterRepository shelters;private final ReliefRequestRepository relief;private final DonationRepository donations;public AdminMetricsController(EmergencyRepository e,ShelterRepository s,ReliefRequestRepository r,DonationRepository d){emergencies=e;shelters=s;relief=r;donations=d;}@GetMapping public Map<String,Object> metrics(){Map<String,Object> m=new LinkedHashMap<>();for(EmergencyStatus s:EmergencyStatus.values())m.put(s.name().toLowerCase(),emergencies.countByStatus(s));m.put("openShelters",shelters.findByStatusOrderByCapacityAvailableDesc("OPEN").size());m.put("openReliefRequests",relief.findByRequestStatusOrderByCreatedAtDesc("OPEN").size());m.put("pledgedDonations",donations.findByDonationStatusOrderByCreatedAtDesc("PLEDGED").size());return m;}}
